div.script:
(function(){
    var translates = {
        en: {
            title: 'Select a default site language',
            button: 'Confirm'
        },
        ru: {
            title: 'Выберите язык сайта по-умолчанию',
            button: 'Подтвердить'
        },
        jp: {
            title: 'デフォルトのサイト言語を選択してください',
            button: '確認する'
        },
        cn: {
            title: '选择默认的网站语言',
            button: '确认'
        },
        la: {
            title: 'Seleccione un idioma predeterminado del sitio',
            button: 'Confirme'
        },
        br: {
            title: 'Selecione um idioma padrão do site',
            button: 'Confirme'
        },
        de: {
            title: 'Select a default site language',
            button: 'Confirm'
        },
        fr: {
            title: 'Select a default site language',
            button: 'Confirm'
        },
        cz: {
            title: 'Select a default site language',
            button: 'Confirm'
        },
    };
    var $toggle          = $('#language_toggle'),
        $dropdown        = $('#language_options'),
        $language_title  = $('#language_title'),
        $language_button = $('#language_button')

    $('#language_options input').click(function(event){
        var $input = $(this);

        $toggle.html($input.parent().text());
        $toggle.prepend($input.next('img').clone());
        $toggle.removeClass('active js_autohide');
        $dropdown.addClass('hidden');
        $language_title.text(translates[this.value].title);
        $language_button.text(translates[this.value].button);
    });
    $toggle.click(function(event){
        event.preventDefault();

        if ($toggle.hasClass('active')) {
            $toggle.removeClass('active js_autohide');
            $dropdown.addClass('hidden');
        } else {
            $toggle.addClass('active js_autohide');
            $dropdown.removeClass('hidden');
        }
    });
})();

header.script:
var searchSection = document.getElementById('search');
var searchQueryInput = document.getElementById('searchQuery');
var searchForm = document.getElementById('searchForm');
var searchIcon = document.getElementById('search-icon');
var trigger = document.querySelector('.js_trigger');

function toggleSearchVisibility() {
  searchSection.classList.toggle('hidden');
}

searchIcon.addEventListener('click', function(event) {
  event.preventDefault();
  toggleSearchVisibility();
  searchQueryInput.focus();
});

trigger.addEventListener('click', function(event) {
  event.preventDefault();
  searchSection.classList.add('hidden');
});

searchForm.addEventListener('submit', function(event) {
  event.preventDefault(); 
  var actionUrl = '/search_web?query=' + encodeURIComponent(searchQueryInput.value);
  window.location.href = actionUrl;
});

function toggleSearchVisibility() {
  searchSection.classList.toggle('hidden');
  if (!searchSection.classList.contains('hidden')) {
    searchQueryInput.focus();
  }
}

document.addEventListener('keydown', function(event) {
  if (event.ctrlKey && event.shiftKey && event.key === 'F') {
    event.preventDefault();
    toggleSearchVisibility();
  }

  if (event.key === 'Escape') {
    if (!searchSection.classList.contains('hidden')) {
      event.preventDefault();
      searchSection.classList.add('hidden');
    }
  }
});

div.script:
				$('#footer_subscribe').submit(function(event){
					event.preventDefault();

					var field = this.email,
						value = field.value;

					if (app.helpers.isValidEmail(field.value)) {
                        fetch($(this).attr('action'), {
                            method: 'POST',
                            body: new FormData(this)
                        });

						// on success
						this.reset();

						var $msg = $('Your message sent!')
							.insertBefore(this.email)
							.click(function(event){
								event.preventDefault();

								$msg.removeClass('show');
							});

						setTimeout(function(){
							$msg.addClass('show');
						}, 0);

						setTimeout(function(){
							$msg.removeClass('show');
						}, 5000);

						setTimeout(function(){
							$(field).blur();
						}, 600);
					} else {
						// on error
						$(field)
							.addClass('invalid')
							.off('keyup')
							.on('keyup', function(){
								if (value.length !== this.value.length) {
									$(this)
										.removeClass('invalid')
										.prev()
										.remove();
								}
							})
							.before('Please enter valid email address');
					}
				});

body.script:
document.addEventListener('DOMContentLoaded', () => {
  const communityDropdowns = Array.from(document.querySelectorAll('.community-dropdown'));

  if (!communityDropdowns.length) {
    return;
  }

  const setDropdownState = (dropdown, isOpen) => {
    const toggle = dropdown.querySelector('.community-dropdown-toggle');
    const menu = dropdown.querySelector('.community-dropdown-menu');

    if (!toggle || !menu) {
      return;
    }

    dropdown.classList.toggle('is-open', isOpen);
    toggle.setAttribute('aria-expanded', isOpen ? 'true' : 'false');
    menu.setAttribute('aria-hidden', isOpen ? 'false' : 'true');
  };

  const closeAllDropdowns = (focusToggle = false) => {
    communityDropdowns.forEach((dropdown) => {
      const toggle = dropdown.querySelector('.community-dropdown-toggle');
      const wasOpen = dropdown.classList.contains('is-open');

      setDropdownState(dropdown, false);

      if (focusToggle && wasOpen && toggle) {
        toggle.focus();
      }
    });
  };

  communityDropdowns.forEach((dropdown, index) => {
    const toggle = dropdown.querySelector('.community-dropdown-toggle');
    const menu = dropdown.querySelector('.community-dropdown-menu');

    if (!toggle || !menu) {
      return;
    }

    if (!menu.id) {
      menu.id = 'community-dropdown-menu-' + (index + 1);
    }

    toggle.setAttribute('aria-controls', menu.id);
    setDropdownState(dropdown, false);

    toggle.addEventListener('click', (event) => {
      event.preventDefault();

      const shouldOpen = !dropdown.classList.contains('is-open');
      closeAllDropdowns();
      setDropdownState(dropdown, shouldOpen);
    });
  });

  document.addEventListener('click', (event) => {
    communityDropdowns.forEach((dropdown) => {
      if (!dropdown.contains(event.target)) {
        setDropdownState(dropdown, false);
      }
    });
  });

  document.addEventListener('keydown', (event) => {
    if (event.key === 'Escape') {
      closeAllDropdowns(true);
    }
  });

  window.addEventListener('scroll', () => {
    closeAllDropdowns();
  }, { passive: true });

  window.addEventListener('resize', () => {
    closeAllDropdowns();
  });
});
